insert into criteria_snapshots (sheet_id, content_hash, criteria, captured_by) values
    ('*', 'sha256:72cb4417c3bc28add2afc8ff14fb45a799515f2e4df4b82bf5aaf1834d6d642f', '[{"Active (Y/N)":"Y","Calibration status":"Uncalibrated","Criterion":"Names a specific driver","Example of good":"Up $65K: Bluewater Health''s one-time backfill ran on our Stratus Compute account (invoice SC-0731).","Feedback when failed":"Name the specific vendor, contract, hire, customer, or event that drove this movement.","ID":"C1","Last reviewed":"","Owner":"Controller","Passes when":"Names the specific cause of the change, identified well enough that a reviewer could look it up: which customer, vendor, contract, hire or event, and what changed with it. Fails when the cause is a category (\"timing\", \"growth\", \"higher volume\"), even with an amount or dates attached, or when the only name given is where the cost was booked or who billed it.","Threshold":"0.43","Why it matters":"A category can''t be checked; a driver can"},{"Active (Y/N)":"Y","Calibration status":"Uncalibrated","Criterion":"Explains why, not just what","Example of good":"Down $25K because we paused the pipeline-monitoring campaign after two quarters of high cost per lead.","Feedback when failed":"Tell me what changed in the business, not just which account moved.","ID":"C2","Last reviewed":"","Owner":"Controller","Passes when":"Says what changed in the business, not only which account moved","Threshold":"0.84","Why it matters":"The reviewer already sees what moved"},{"Active (Y/N)":"Y","Calibration status":"Uncalibrated","Criterion":"Separates one-time from recurring","Example of good":"One-time: the backfill finished Jul 19, so August returns to the run rate.","Feedback when failed":"Will this repeat next period? Say whether it''s one-time or recurring.","ID":"C3","Last reviewed":"","Owner":"Controller","Passes when":"States whether the driver repeats next period","Threshold":"0.15","Why it matters":"Drives whether forecasts should change"},{"Active (Y/N)":"Y","Calibration status":"Uncalibrated","Criterion":"Points to evidence","Example of good":"See Stratus invoice SC-0731 and JE 7-114.","Feedback when failed":"Point me to something I can pull: the invoice, JE, contract, or headcount report.","ID":"C4","Last reviewed":"","Owner":"Controller","Passes when":"References something a reviewer could pull: invoice, JE, contract, headcount report","Threshold":"0.74","Why it matters":"Makes the review a check, not a conversation"},{"Active (Y/N)":"Y","Calibration status":"Uncalibrated","Criterion":"Sizes each driver","Example of good":"Orion Freight $135K, Cobalt seats $41K, renewal uplifts $12K: $188K in total.","Feedback when failed":"Put a number on each driver, or say how much is still unexplained.","ID":"C5","Last reviewed":"","Owner":"Controller","Passes when":"Gives an amount or share for each driver named, or says what is still unexplained","Threshold":"0.36","Why it matters":"Gives the arithmetic check something to test and makes a partial explanation visible"},{"Active (Y/N)":"Y","Calibration status":"Uncalibrated","Criterion":"Says more than the row","Example of good":"Names what happened (a customer backfill, a price change), not just that hosting rose $65K.","Feedback when failed":"This repeats the numbers already in the row. Tell me what happened, not what moved.","ID":"RESTATE","Last reviewed":"","Owner":"System","Passes when":"Adds something beyond the figures already in the row: more than the account name, the direction of the change, and its size","Threshold":"0.85","Why it matters":"The row already shows the numbers"},{"Active (Y/N)":"Y","Calibration status":"Deterministic","Criterion":"Amounts add up","Example of good":"Drivers of $52K and $13K for a $65K variance.","Feedback when failed":"The amounts you cite don''t add up to the variance. Check each driver''s amount, or say how much is still unexplained.","ID":"ARITH","Last reviewed":"","Owner":"System","Passes when":"The amounts cited for the drivers sum to the variance, within the tolerance in Settings (rule in code; not editable here)","Threshold":"n/a","Why it matters":"A partial or mistyped explanation should be visible before review"},{"Active (Y/N)":"Y","Calibration status":"Deterministic","Criterion":"Not copied from another line","Example of good":"Each line names its own driver.","Feedback when failed":"This is word for word the same as another line. Explain what drove this account specifically.","ID":"DUP","Last reviewed":"","Owner":"System","Passes when":"The commentary is not identical to another line''s in the same close (rule in code; not editable here)","Threshold":"n/a","Why it matters":"Copied text explains neither line"},{"Active (Y/N)":"Y","Calibration status":"Heuristic","Criterion":"Not a template","Example of good":"Two salary lines that each name their own hires.","Feedback when failed":"This reads almost the same as another line. Make sure it explains this account''s movement, not a shared template.","ID":"NEAR","Last reviewed":"","Owner":"System","Passes when":"The commentary is not nearly identical to another line''s; similarity threshold in Settings (rule in code)","Threshold":"Settings","Why it matters":"Templates hide the differences between accounts"}]'::jsonb, 'seed')
